from pathlib import Path
p=Path('work/test_graph_float_curve_sampler.cpp')
s=p.read_text().replace('#include "graph_float_curve_sampler.h"','#include "graph_float_curve_sampler.h"\n#include "clip_hierarchy.h"\n#include "channel_binding.h"\n#include "session_expression_runtime.h"')
s=s.replace('saveGraph(r.graph,argv[2]);','''uint32_t channel=0xffffffff;for(uint32_t i=0;i<start;++i)if(r.graph.strings.at(r.graph.elements[i].type)=="DmeChannel"){ChannelBinding candidate(r.graph,i);if(candidate.destination.present()&&candidate.destination.scalarType==3){channel=i;break;}}if(channel==0xffffffff)throw std::runtime_error("no float destination channel");auto channelLog=runtimeAttribute(r.graph,channel,"log");channelLog->values[0].reference=start;auto mode=runtimeAttribute(r.graph,channel,"mode");setWireU32(mode->values[0],3);ChannelBinding binding(r.graph,channel);SessionAttributeChanges changes;if(!executeSessionFloatPlay(r.graph,binding,20000,&changes)||wireFloat(runtimeAttribute(r.graph,binding.destination.element,binding.destination.attribute)->values.at(binding.destination.index))!=2)throw std::runtime_error("curve channel write failed");saveGraph(r.graph,argv[2]);''')
